#!/usr/bin/env bash
# Results and logs default to this checkout so the script runs without the original
# /NAS mount; override with VITA_RESULTS_DIR / VITA_LOG_DIR. This is the same data dir
# the Python side anchors on (vita.utils.utils.DATA_DIR).
