OUT_DIR="${VITA_RESULTS_DIR:-$REPO_DIR/data/results}"
LOG_DIR="${VITA_LOG_DIR:-$REPO_DIR/data/logs}"
mkdir -p "$OUT_DIR" "$LOG_DIR"

